import os, json, logging, boto3
from botocore.exceptions import ClientError

logger = logging.getLogger()
logger.setLevel(logging.INFO)

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['TABLE_NAME'])

def lambda_handler(event, context):
    task_id = event.get('pathParameters', {}).get('id')
    if not task_id:
        return {
            'statusCode': 400,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'error': 'Task ID is required'})
        }
    try:
        body = json.loads(event.get('body', '{}'))
        if not body:
            return {
                'statusCode': 400,
                'headers': {'Content-Type': 'application/json'},
                'body': json.dumps({'error': 'Update data required'})
            }
        update_expr = 'SET ' + ', '.join(f'#{k}=:{k}' for k in body.keys())
        expr_attr_names = {f'#{k}': k for k in body.keys()}
        expr_attr_values = {f':{k}': v for k, v in body.items()}
        response = table.update_item(
            Key={'taskId': task_id},
            UpdateExpression=update_expr,
            ExpressionAttributeNames=expr_attr_names,
            ExpressionAttributeValues=expr_attr_values,
            ReturnValues='ALL_NEW'
        )
        updated_item = response.get('Attributes')
        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps(updated_item)
        }
    except (json.JSONDecodeError, TypeError) as e:
        logger.error(f'Invalid input: {e}')
        return {
            'statusCode': 400,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'error': 'Invalid request body'})
        }
    except ClientError as e:
        logger.error(f'DynamoDB error: {e}')
        return {
            'statusCode': 500,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'error': 'Internal server error'})
        }

